def solve():
    # M(k, c) is the max moves to get 2^k using c cells
    # M(k, c) = max(1, M(k-1, c) + M(k-1, c-1) + 1)
    # base cases: M(0, c) = 1 for c >= 1

    # We need M(40, 9)
    k_max = 40
    c_max = 9

    M = [[0] * (c_max + 1) for _ in range(k_max + 1)]

    for c in range(1, c_max + 1):
        M[0][c] = 1

    for k in range(1, k_max + 1):
        for c in range(1, c_max + 1):
            # Option 1: just place 2^k
            res = 1
            # Option 2: produce two 2^{k-1}
            if c >= 2:
                res = max(res, M[k-1][c] + M[k-1][c-1] + 1)
            M[k][c] = res

    return M[40][9]

print(solve())

